const FALLBACK_REPLY = 'Não consegui responder agora. Tente novamente.';
const cur = $input.first().json || {};

// Falha da IA já montada: apenas repassa.
if (cur.response && typeof cur.statusCode === 'number') return [{ json: { statusCode: cur.statusCode, response: cur.response } }];

const req = $('Validar requisição').first().json;

// Sessão expirada durante uma consulta: o Xano devolveu 401 a alguma ferramenta.
// Só o status sai daqui; as etapas (com dados do Xano) não seguem para a resposta.
const steps = Array.isArray(cur.intermediateSteps) ? cur.intermediateSteps : [];
const sessaoExpirada = steps.some((s) => {
  let obs = s && s.observation;
  if (typeof obs !== 'string') { try { obs = JSON.stringify(obs); } catch (e) { obs = ''; } }
  return /ERROR_CODE_UNAUTHORIZED/.test(obs || '');
});
if (sessaoExpirada) {
  return [{ json: {
    statusCode: 401,
    response: {
      ok: false,
      request_id: req.request_id ?? null,
      conversation_id: req.conversation_id ?? null,
      reply: 'Sua sessão expirou ou não pôde ser confirmada. Entre novamente no Vet Tech para consultar os dados dos seus pets.',
      error: { code: 'SESSION_INVALID' },
    },
  } }];
}

const raw = typeof cur.output === 'string' ? cur.output : cur.text;
let reply = typeof raw === 'string' ? raw.trim() : '';
let handoff = null;
let identity = null;
try { identity = $('Avaliar identidade').first().json; } catch (e) {}
const tutorConfirmed = req.user?.authenticated === true && req.user?.role === 'tutor'
  && identity?.identidade_ok === true && identity?.modo === 'tutor';
if (tutorConfirmed) {
  try {
    const parsed = JSON.parse(reply);
    if (!parsed || Array.isArray(parsed) || typeof parsed.reply !== 'string'
      || Object.keys(parsed).some(k => !['reply', 'handoff'].includes(k))) throw new Error('invalid');
    reply = parsed.reply.trim();
    if (parsed.handoff !== null && parsed.handoff !== undefined) {
      const h = parsed.handoff;
      const reason = 'Solicitação de orientação veterinária após conversa com o assistente.';
      if (!h || Array.isArray(h) || h.type !== 'veterinary' || h.reason !== reason
        || Object.keys(h).some(k => !['type', 'reason'].includes(k))) throw new Error('invalid');
      handoff = { type: 'veterinary', reason };
    }
  } catch (e) { reply = ''; handoff = null; }
}

// Proteção extra: nunca devolver o token da sessão.
let token = '';
try { token = String((($('Receber pergunta (Webhook)').first().json.headers) || {})['x-vettech-user-token'] || '').trim(); } catch (e) { token = ''; }
if (token && reply.includes(token)) reply = '';

if (!reply) {
  return [{ json: {
    statusCode: 503,
    response: {
      ok: false,
      request_id: req.request_id ?? null,
      conversation_id: req.conversation_id ?? null,
      reply: FALLBACK_REPLY,
      error: { code: 'AI_UNAVAILABLE' },
    },
  } }];
}

return [{ json: {
  statusCode: 200,
  response: {
    ok: true,
    request_id: req.request_id,
    conversation_id: req.conversation_id,
    reply,
    error: null,
    ...(handoff ? { handoff } : {}),
  },
} }];
